def max_chain_length(lst, n):
    sorted_lst = sorted(lst, key=lambda x: x.b)
    current_end = -float('inf')
    count = 0
    for pair in sorted_lst:
        if pair.a > current_end:
            count += 1
            current_end = pair.b
    return count

