import re

def move_num(s):
    tokens = re.findall(r'\d+|\D+', s)
    non_digits = []
    digits = []
    for token in tokens:
        if token.isdigit():
            digits.append(token)
        else:
            non_digits.append(token)
    return ''.join(non_digits) + ''.join(digits)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
