    check(2, move_num('Avengers124Assemble'), 'AvengersAssemble124')
    check(3, move_num('Its11our12path13to14see15things16do17things'), 'Itsourpathtoseethingsdothings11121314151617')

def largest_subset(lst, n):
    if not lst:
        return 0
    lst_sorted = sorted(lst)
    dp = [1] * len(lst_sorted)
    max_len = 1
    for i in range(len(lst_sorted)):
        for j in range(i):
            if lst_sorted[i] % lst_sorted[j] == 0:
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
        max_len = max(max_len, dp[i])
    return max_len

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
