def get_median(lst, lst2, n):
    merged = []
    i = j = 0
    while i < n and j < n:
        if lst[i] < lst2[j]:
            merged.append(lst[i])
            i += 1
        else:
            merged.append(lst2[j])
            j += 1
    while i < n:
        merged.append(lst[i])
        i += 1
    while j < n:
        merged.append(lst2[j])
        j += 1
    total = 2 * n
    mid = total // 2
    return (merged[mid-1] + merged[mid]) / 2

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, get_median([1, 12, 15, 26, 38], [2, 13, 17, 30, 45], 5), 16.0)
    check(2, get_median([2,4,8,9], [7,13,19,28], 4), 8.5)
