import math

def sum_Square(n):
    """একটি পাইথন ফাংশন লিখুন যা দিয়ে পরিচালিত যে, প্রদত্ত সংখ্যাটি দুইটি বর্গক্ষেত্রের যোগফল দ্বারা উপস্থাপিত হতে পারে কি না।
    Translated: Write a Python function to check if a given number can be represented as the sum of two squares."""
    max_a = math.isqrt(n)
    for a in range(max_a + 1):
        rem = n - a * a
        if rem < 0:
            continue
        b = math.isqrt(rem)
        if b * b == rem:
            return True
    return False

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, sum_Square(25), True)
    check(2, sum_Square(24), False)
    check(3, sum_Square(17), True)

