def sum_Of_Primes(n):
    def is_prime(k):
        if k <= 1:
            return False
        if k == 2:
            return True
        if k % 2 == 0:
            return False
        for i in range(3, int(k**0.5) +1, 2):
            if k % i == 0:
                return False
        return True
    total = 0
    for num in range(2, n+1):
        if is_prime(num):
            total += num
    return total

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, sum_Of_Primes(10), 17)
    check(2, sum_Of_Primes(20), 77)
    check(3, sum_Of_Primes(5), 10)
    check(4, sum_Of_Primes(1), 0)
    check(5, sum_Of_Primes(2), 2)

def freq_element(tup):
    freq = {}
    for num in tup:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1
    items = [f"{k}:{v}" for k, v in freq.items()]
    return "{" + ",".join(items) + "}"

