def min_jumps(lst, n):
    if n <= 1:
        return 0
    jumps = 0
    current_end = 0
    farthest = 0
    for i in range(n - 1):
        farthest = max(farthest, i + lst[i])
        if i == current_end:
            jumps += 1
            current_end = farthest
            if farthest >= n - 1:
                return jumps
    return jumps if farthest >= n -1 else -1

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, min_jumps([1,3,6,1,0,9],6),3)
    check(2, min_jumps([1,3,5,8,9,2,6,7,6,8,9],11),3)
    check(3, min_jumps([1]*11,11),10)
    check(4, min_jumps([3,2,1,0,4],5), -1)

