def min_Swaps(s, s2):
    if len(s) != len(s2):
        return "Not Possible"
    if s.count('1') != s2.count('1'):
        return "Not Possible"
    countA = 0
    countB = 0
    for a, b in zip(s, s2):
        if a != b:
            if a == '0' and b == '1':
                countA += 1
            else:
                countB += 1
    if countA != countB:
        return "Not Possible"
    return countA

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, min_Swaps('1101', '1110'), 1)
    check(2, min_Swaps('1111', '0100'), 'Not Possible')
    check(3, min_Swaps('1110000', '0001101'), 3)
    check(4, min_Swaps('10', '01'), 1)
    check(5, min_Swaps('000', '111'), "Not Possible")

