    check(2, equilibrium_index([-7, 1,5,2,-4,3,0]),3)
    check(3, equilibrium_index([1,2,3]), -1)

def removals(lst, n, n2):
    lst_sorted = sorted(lst)
    max_window = 0
    left = 0
    for right in range(len(lst_sorted)):
        while lst_sorted[right] - lst_sorted[left] > n2:
            left += 1
        current = right - left + 1
        if current > max_window:
            max_window = current
    return len(lst) - max_window

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, removals([1,3,4,9,10,11,12,17,20], 9,4),5)
    check(2, removals([1,5,6,2,8],5,2),3)
    check(3, removals([1,2,3,4,5,6],6,3),2)

