def product_Equal(n):
    digits = [int(c) for c in str(n)]
    product_odd = 1
    product_even = 1
    for i in range(len(digits)):
        if (i + 1) % 2 == 1:
            product_odd *= digits[i]
        else:
            product_even *= digits[i]
    return product_odd == product_even

