def count_Fac(n):
    if n < 1:
        return 0
    sum_exp = 0
    current = n
    i = 2
    while i * i <= current:
        if current % i == 0:
            count = 0
            while current % i == 0:
                count +=1
                current = current // i
            sum_exp += count
        i +=1
    if current >1:
        sum_exp +=1
    return sum_exp -1

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, count_Fac(24), 3)
    check(2, count_Fac(12), 2)
    check(3, count_Fac(4), 1)

