import math

def sd_calc(lst):
    n = len(lst)
    mean = sum(lst) / n
    sum_sq_diff = sum((x - mean)**2 for x in lst)
    variance = sum_sq_diff / (n - 1)
    return math.sqrt(variance)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, sd_calc([4,2,5,8,6]), 2.23606797749979)
    check(2, sd_calc([1,2,3,4,5,6,7]), 2.160246899469287)
    check(3, sd_calc([5,9,10,15,6,4]),4.070217029430577)

