def maxAverageOfPath(lst, n):
    dp = [[0]*n for _ in range(n)]
    dp[0][0] = lst[0][0]
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + lst[0][j]
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + lst[i][0]
    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + lst[i][j]
    return dp[n-1][n-1] / (2 * n -1)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, maxAverageOfPath([[1,2,3],[6,5,4],[7,3,9]], 3), 5.2)
    check(2, maxAverageOfPath([[2,3,4],[7,6,5],[8,4,10]], 3), 6.2)
    check(3, maxAverageOfPath([[3,4,5],[8,7,6],[9,5,11]], 3), 7.2)

