def find_first_occurrence(lst, n):
    left = 0
    right = len(lst) - 1
    res = -1
    while left <= right:
        mid = (left + right) // 2
        if lst[mid] == n:
            res = mid
            right = mid - 1
        elif lst[mid] < n:
            left = mid + 1
        else:
            right = mid - 1
    return res

