def toggle_middle_bits(n):
    binary = bin(n)[2:]
    if len(binary) < 3:
        return n
    first = binary[0]
    last = binary[-1]
    middle = binary[1:-1]
    toggled_middle = ''.join(['1' if c == '0' else '0' for c in middle])
    new_binary = first + toggled_middle + last
    return int(new_binary, 2)

