def divisible_by_digits(n, n2):
    result = []
    for num in range(n, n2 + 1):
        digits = [int(c) for c in str(num)]
        if 0 in digits:
            continue
        valid = True
        for d in digits:
            if num % d != 0:
                valid = False
                break
        if valid:
            result.append(num)
    return result

