def Diff(lst, lst2):
    set2 = set(lst2)
    evens = []
    odds = []
    for num in lst:
        if num not in set2:
            if num % 2 == 0:
                evens.append(num)
            else:
                odds.append(num)
    part2 = [x for x in lst2 if x not in set(lst)]
    return evens + odds + part2

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
