def check_expression(s):
    stack = []
    closing = {')': '(', ']': '[', '}': '{'}
    opening = {'(', '[', '{'}
    for char in s:
        if char in opening:
            stack.append(char)
        elif char in closing:
            if not stack:
                return False
            if stack.pop() != closing[char]:
                return False
    return len(stack) == 0

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

