def rgb_to_hsv(n, n2, n3):
    original_r = n
    original_g = n2
    original_b = n3

    r = original_r / 255.0
    g = original_g / 255.0
    b = original_b / 255.0

    cmax = max(r, g, b)
    cmin = min(r, g, b)
    delta = cmax - cmin

    max_val = max(original_r, original_g, original_b)

    if delta == 0:
        h = 0.0
    else:
        if original_r == max_val:
            h_part = (g - b) / delta
        elif original_g == max_val:
            h_part = (b - r) / delta
        else:
            h_part = (r - g) / delta

        if original_r == max_val:
            h = (h_part % 6)
        elif original_g == max_val:
            h = h_part + 2
        else:
            h = h_part + 4

        h *= 60
        h %= 360.0

    if cmax == 0:
        s = 0.0
    else:
        s = (delta / cmax) * 100

    v = cmax * 100

    return (h, s, v)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, rgb_to_hsv(255, 255, 255), (0, 0.0, 100.0))
    check(2, rgb_to_hsv(0, 215, 0), (120.0, 100.0, 84.31372549019608))
    check(3, rgb_to_hsv(10, 215, 110), (149.26829268292684, 95.34883720930233, 84.31372549019608))

