def right_insertion(lst, n):
    low = 0
    high = len(lst)
    while low < high:
        mid = (low + high) // 2
        if lst[mid] > n:
            high = mid
        else:
            low = mid + 1
    return low

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, right_insertion([1, 2, 4, 5], 6), 4)
    check(2, right_insertion([1, 2, 4, 5], 3), 2)
    check(3, right_insertion([1, 2, 4, 5], 7), 4)

