def sum_in_Range(n, n2):
    if n > n2:
        return 0
    first_odd = n if n % 2 else n + 1
    if first_odd > n2:
        return 0
    last_odd = n2 if n2 % 2 else n2 -1
    if last_odd < first_odd:
        return 0
    count = ((last_odd - first_odd) // 2) + 1
    return (first_odd + last_odd) * count // 2

