def count_duplic(lst):
    if not lst:
        return ([], [])
    elements = []
    counts = []
    current = lst[0]
    current_count = 1
    for num in lst[1:]:
        if num == current:
            current_count += 1
        else:
            elements.append(current)
            counts.append(current_count)
            current = num
            current_count = 1
    elements.append(current)
    counts.append(current_count)
    return (elements, counts)

