def max_sub_array_sum(lst, n):
    if not lst:
        return 0
    current_sum = lst[0]
    current_length = 1
    max_sum = current_sum
    max_length = current_length
    for num in lst[1:]:
        temp_sum = current_sum + num
        if temp_sum >= num:
            current_sum = temp_sum
            current_length += 1
        else:
            current_sum = num
            current_length = 1
        if current_sum > max_sum:
            max_sum = current_sum
            max_length = current_length
        elif current_sum == max_sum:
            if current_length > max_length:
                max_length = current_length
    return max_length

