    check(6, find_Digits(3), 1)

import heapq

def find_platform(lst, lst2, n):
    events = sorted(zip(lst, lst2), key=lambda x: x[0])
    heap = []
    max_platforms = 0
    for arrival, departure in events:
        while heap and heap[0] <= arrival:
            heapq.heappop(heap)
        heapq.heappush(heap, departure)
        current = len(heap)
        if current > max_platforms:
            max_platforms = current
    return max_platforms

