def Sum_of_Inverse_Divisors(n, n2):
    divisors = []
    for i in range(1, n + 1):
        if n % i == 0:
            divisors.append(i)
    sum_reciprocal = sum(1.0 / d for d in divisors)
    sum_divisors = sum(divisors)
    result = (sum_reciprocal * n2) / sum_divisors
    return round(result, 2)

