def n_common_words(s, n):
    words = s.split()
    if not words:
        return []
    first_occurrence = {}
    for idx, word in enumerate(words):
        if word not in first_occurrence:
            first_occurrence[word] = idx
    freq = {}
    for word in words:
        freq[word] = freq.get(word, 0) + 1
    unique_words = list(freq.keys())
    unique_words.sort(key=lambda x: (-freq[x], first_occurrence[x]))
    top_n = unique_words[:n]
    return [(word, freq[word]) for word in top_n]

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

