def extract_elements(lst, n):
    if not lst:
        return []
    groups = []
    current_group = [lst[0]]
    for elem in lst[1:]:
        if elem == current_group[-1]:
            current_group.append(elem)
        else:
            groups.append(current_group)
            current_group = [elem]
    groups.append(current_group)
    elements = []
    for group in groups:
        if len(group) >= 2:
            elements.append(group[0])
    return elements[:n]

