def num_comm_div(n, n2):
    a, b = abs(n), abs(n2)
    x, y = a, b
    while y:
        x, y = y, x % y
    gcd_val = x
    if gcd_val == 0:
        return 0
    count = 0
    sqrt_k = int(gcd_val ** 0.5)
    for i in range(1, sqrt_k +1):
        if gcd_val % i == 0:
            count += 1 if i * i == gcd_val else 2
    return count

