def find_Min_Sum(n):
    if n == 1:
        return 0
    total = 0
    while n % 2 == 0:
        total += 2
        n //= 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            total += i
            n //= i
        i += 2
    if n > 1:
        total += n
    return total

