def modular_sum(lst, n, n2):
    m = n2
    if m == 0:
        return False
    current = set()
    for num in lst:
        rem = num % m
        if rem == 0:
            return True
        new_subs = {rem}
        for r in current:
            new_r = (r + rem) % m
            new_subs.add(new_r)
        if 0 in new_subs:
            return True
        current.update(new_subs)
    return 0 in current

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, modular_sum([3, 1, 7, 5], 4, 6), True)
    check(2, modular_sum([1,7], 2,5), False)
    check(3, modular_sum([1,6], 2,5), False)

def radix_sort(lst):
    if not lst:
        return []
    arr = lst.copy()
    max_num = max(arr)
    exp = 1
    while max_num // exp > 0:
        buckets = [[] for _ in range(10)]
        for num in arr:
            digit = (num // exp) % 10
            buckets[digit].append(num)
        arr = []
        for b in buckets:
            arr.extend(b)
        exp *= 10
    return arr

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, radix_sort([15, 79, 25, 68, 37]), [15,25,37,68,79])
    check(2, radix_sort([9,11,8,7,3,2]), [2,3,7,8,9,11])
    check(3, radix_sort([36,12,24,26,29]), [12,24,26,29,36])

