def sqrt_root(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    low, high = 0, n
    while low <= high:
        mid = (low + high) // 2
        mid_sq = mid * mid
        if mid_sq == n:
            return mid
        elif mid_sq < n:
            low = mid + 1
        else:
            high = mid -1
    return high

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, sqrt_root(4), 2)
