def check_string(s):
    conditions = [
        lambda x: any(c.isupper() for c in x),
        lambda x: any(c.isdigit() for c in x),
        lambda x: len(x) >= 8
    ]
    messages = [
        "String must have 1 upper case character.",
        "String must have 1 number.",
        "String length should be atleast 8."
    ]
    errors = []
    for cond, msg in zip(conditions, messages):
        if not cond(s):
            errors.append(msg)
    return ["Valid string."] if not errors else errors

