def capitalize_first_last_letters(s):
    words = s.split()
    processed = []
    for word in words:
        if not word:
            continue
        first = word[0].upper()
        last = word[-1].upper()
        middle = word[1:-1]
        new_word = first + middle + last
        processed.append(new_word)
    return ' '.join(processed)

