import math

def check_abundant(n):
    if n <= 1:
        return False
    sum_div = 1
    sqrt_n = int(math.sqrt(n))
    for i in range(2, sqrt_n + 1):
        if n % i == 0:
            sum_div += i
            other = n // i
            if other != i:
                sum_div += other
    return sum_div > n

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, check_abundant(12), True)
    check(2, check_abundant(15), False)
    check(3, check_abundant(18), True)
    check(4, check_abundant(6), False)
    check(5, check_abundant(24), True)

