def max_sub_array_sum(lst, n):
    if n == 0:
        return 0
    max_current = max_global = lst[0]
    for i in range(1, n):
        current_num = lst[i]
        max_current = max(current_num, max_current + current_num)
        if max_current > max_global:
            max_global = max_current
    return max_global

