def remove_words(lst, lst2):
    result = []
    for s in lst:
        words = s.split()
        filtered = []
        for word in words:
            include = True
            for forbidden in lst2:
                if forbidden in word:
                    include = False
                    break
            if include:
                filtered.append(word)
        joined = ' '.join(filtered)
        result.append(joined)
    return result

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, remove_words(['Red color', 'Orange#', 'Green', 'Orange @', 'White'], ['#', 'color', '@']), ['Red', '', 'Green', 'Orange', 'White'])
    check(2, remove_words(['Red &', 'Orange+', 'Green', 'Orange @', 'White'], ['&', '+', '@']), ['Red', '', 'Green', 'Orange', 'White'])
    check(3, remove_words(['Red &', 'Orange+', 'Green', 'Orange @', 'White'], ['@']), ['Red &', 'Orange+', 'Green', 'Orange', 'White'])

def max_sum_pair_diff_lessthan_K(lst, n, n2):
    lst_sorted = sorted(lst)
    total = 0
    i = n - 1
    while i >= 1:
        if lst_sorted[i] - lst_sorted[i-1] < n2:
            total += lst_sorted[i] + lst_sorted[i-1]
            i -= 2
        else:
            i -= 1
    return total

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

