def count_no(n, n2, n3, n4):
    divisors = [n, n2, n3, n4]
    divisors = [d for d in divisors if d > 1]
    current = 1
    count = 0
    while True:
        if all(current % d != 0 for d in divisors):
            count += 1
            if count == n:
                return current
        current += 1

