def extract_even(tup):
    result = []
    for elem in tup:
        if isinstance(elem, tuple):
            sub_result = extract_even(elem)
            result.append(sub_result)
        else:
            if elem % 2 == 0:
                result.append(elem)
    return tuple(result)

