    check(3, diff_even_odd([1,5,7,9,10]), 9)

def min_Swaps(s, s2):
    if len(s) != len(s2):
        return "Not Possible"
    if s.count('1') != s2.count('1'):
        return "Not Possible"
    a = b = 0
    for sc, s2c in zip(s, s2):
        if sc != s2c:
            if sc == '0':
                a += 1
            else:
                b += 1
    return a  # Since a must equal b here

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, min_Swaps('1101', '1110'), 1)
    check(2, min_Swaps('111', '000'), 'Not Possible')
    check(3, min_Swaps('111', '110'), 'Not Possible')
    check(4, min_Swaps('01', '10'), 1)
    check(5, min_Swaps('0011', '1100'), 2)
    check(6, min_Swaps('1010', '1010'), 0)
    check(7, min_Swaps('1', '11'), 'Not Possible')

