def find_kth(lst, lst2, n, n2, n3):
    i = j = 0
    count = 0
    k = n3
    while i < n and j < n2:
        if lst[i] < lst2[j]:
            current = lst[i]
            i += 1
        else:
            current = lst2[j]
            j += 1
        count += 1
        if count == k:
            return current
    while i < n:
        current = lst[i]
        i += 1
        count += 1
        if count == k:
            return current
    while j < n2:
        current = lst2[j]
        j += 1
        count += 1
        if count == k:
            return current
    return -1  # Assuming valid input where k is within range

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, find_kth([2,3,6,7,9], [1,4,8,10],5,4,5), 6)
    check(2, find_kth([100,112,256,349,770], [72,86,113,119,265,445,892],5,7,7), 256)
    check(3, find_kth([3,4,7,8,10], [2,5,9,11],5,4,6),8)

